const networks=[['X','𝕏','x'],['LinkedIn','in','linkedin'],['Instagram','◎','insta'],['YouTube','▶','youtube'],['Facebook','f','facebook'],['Threads','@','threads']];
const upcoming=[{day:'18',month:'NOV',title:'Building better products starts with...',time:'10:30 AM',p:['linkedin','x']},{day:'18',month:'NOV',title:'A closer look at the details ✨',time:'4:00 PM',p:['insta','facebook']},{day:'19',month:'NOV',title:'Three lessons from our latest launch',time:'9:15 AM',p:['x','threads']}];
const projects=[{name:'Acme Products',desc:'Main product and company channels',posts:8,accounts:5,color:'#6c5ce7'},{name:'Northstar Labs',desc:'Developer community and launches',posts:4,accounts:3,color:'#f39b5f'},{name:'Arjun Personal',desc:'Personal brand and thought leadership',posts:2,accounts:2,color:'#35ae80'}];
const accounts=[['LinkedIn','Acme Products','in','linkedin'],['Instagram','@acmeproducts','◎','insta'],['X','@acmeproducts','𝕏','x'],['YouTube','Acme Products','▶','youtube'],['Facebook','Acme Products','f','facebook']];
function renderUpcoming(){document.querySelector('#upcomingList').innerHTML=upcoming.map(x=>`<div class="upcoming-item"><div class="date-tile"><b>${x.month}</b><strong>${x.day}</strong></div><div><h3>${x.title}</h3><p>${x.time} · Acme Products</p></div><div class="platforms">${x.p.map(p=>`<span class="platform-dot ${p}">${p==='linkedin'?'in':p==='insta'?'◎':'●'}</span>`).join('')}</div></div>`).join('')}
function renderProjects(){document.querySelector('#projectGrid').innerHTML=projects.map(x=>`<article class="project-card"><div class="project-color" style="background:${x.color}"></div><h2>${x.name}</h2><p>${x.desc}</p><div class="project-meta"><span>${x.accounts} accounts</span><strong>${x.posts} scheduled</strong></div></article>`).join('')}
function renderAccounts(){document.querySelector('#accountGrid').innerHTML=accounts.map(x=>`<article class="account-card"><span class="network-icon ${x[3]}">${x[2]}</span><div><h2>${x[0]}</h2><p>${x[1]}</p><p class="status">● Connected</p></div><button class="text-button">Manage</button></article>`).join('')}
function renderChannels(){const rows=[['LinkedIn','in','linkedin',142600,92,9.8],['Instagram','◎','insta',98400,73,8.7],['YouTube','▶','youtube',75200,58,12.1],['X','𝕏','x',66400,48,6.3]];document.querySelector('#channelRows').innerHTML=rows.map(r=>`<div class="channel-row"><div class="channel-name"><span class="platform-chip ${r[2]}">${r[1]}</span>${r[0]}</div><div class="bar"><i style="width:${r[4]}%"></i></div><strong>${(r[3]/1000).toFixed(1)}K</strong><strong>${r[5]}%</strong></div>`).join('')}
function renderCalendar(){const heads=['MON','TUE','WED','THU','FRI','SAT','SUN'];let html=heads.map(h=>`<div class="cal-head">${h}</div>`).join('');for(let i=26;i<=56;i++){const day=i<=30?i:i-30;const muted=i<=30||i>60;let ev='';if([33,35,39,42,48,49,52].includes(i))ev=`<div class="cal-event">${i%2?'Product story':'Weekly update'} · ${i%3?'10:30':'16:00'}</div>`;html+=`<div class="cal-day ${muted?'muted-day':''}">${day}${ev}</div>`}document.querySelector('#calendarGrid').innerHTML=html}
function navigate(id){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===id));document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===id));document.querySelector('.sidebar').classList.remove('open');scrollTo({top:0,behavior:'smooth'})}
function showToast(title,msg){const t=document.querySelector('#toast');t.querySelector('strong').textContent=title;t.querySelector('p').textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function setModal(id,open){const el=document.querySelector(id);el.classList.toggle('open',open);el.setAttribute('aria-hidden',String(!open))}
document.querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();navigate(a.dataset.page)}));document.querySelectorAll('[data-nav]').forEach(a=>a.addEventListener('click',()=>navigate(a.dataset.nav)));document.querySelectorAll('[data-open-composer]').forEach(b=>b.addEventListener('click',()=>setModal('#composerModal',true)));document.querySelectorAll('.close-modal').forEach(b=>b.addEventListener('click',()=>setModal('#composerModal',false)));document.querySelector('#connectAccount').addEventListener('click',()=>setModal('#connectModal',true));document.querySelector('.close-connect').addEventListener('click',()=>setModal('#connectModal',false));document.querySelector('#menuButton').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));
document.querySelectorAll('.range button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.range button').forEach(x=>x.classList.remove('active'));b.classList.add('active');showToast('Range updated',`Showing the last ${b.textContent}.`)}));document.querySelectorAll('#platformSelect button').forEach(b=>b.addEventListener('click',()=>b.classList.toggle('selected')));document.querySelector('#postText').addEventListener('input',e=>document.querySelector('#charCount').textContent=e.target.value.length);document.querySelector('#uploadButton').addEventListener('click',()=>showToast('Media picker','Upload support is ready for API integration.'));
document.querySelector('#schedulePost').addEventListener('click',()=>{const text=document.querySelector('#postText').value.trim();if(!text){showToast('Add some text','Write a caption before scheduling.');return}upcoming.unshift({day:document.querySelector('#scheduleDate').value.split('-')[2],month:'NOV',title:text,time:document.querySelector('#scheduleTime').value,p:['x','linkedin']});renderUpcoming();setModal('#composerModal',false);showToast('Post scheduled','Your post was added to the publishing queue.')});
document.querySelector('#addProject').addEventListener('click',()=>{projects.push({name:'New campaign',desc:'A fresh social publishing project',posts:0,accounts:0,color:'#56a9d8'});renderProjects();showToast('Project created','Your new project is ready to customise.')});document.querySelector('#saveSettings').addEventListener('click',()=>showToast('Settings saved','Workspace preferences updated.'));
document.querySelector('#networkList').innerHTML=networks.map(n=>`<button class="network-option" data-network="${n[0]}"><span class="network-icon ${n[2]}">${n[1]}</span>${n[0]}</button>`).join('');document.querySelectorAll('.network-option').forEach(b=>b.addEventListener('click',()=>{setModal('#connectModal',false);showToast(`${b.dataset.network} selected`,'OAuth credentials are required for live connection.')}));document.querySelectorAll('.modal-backdrop').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)setModal('#'+m.id,false)}));
renderUpcoming();renderProjects();renderAccounts();renderChannels();renderCalendar();
